function validate([root]) {
  if (!Array.isArray(root) || root.length === 0 || root[0] === null) return 'The tree needs at least two nodes.';
  const values = root.filter(v => v !== null);
  if (values.length < 2) return 'The tree needs at least two nodes, so there is an edge to cut.';
  if (values.length > 50000) return 'The tree has at most 5 * 10^4 nodes.';
  if (values.some(v => !Number.isInteger(v) || v < 1 || v > 10000)) return 'Every node value is an integer from 1 to 10^4.';
  return null;
}

