function maxProduct(root) {
  const sums = [];
  const subtreeSum = (node) => {
    if (node === null) {
      return 0;
    }
    const sum = node.val + subtreeSum(node.left) + subtreeSum(node.right);
    sums.push(sum);
    return sum;
  };
  const total = subtreeSum(root);
  let best = 0;
  for (const sum of sums) {
    best = Math.max(best, sum * (total - sum));
  }
  return best % 1000000007;
}

