  // Cut above every non-root node in turn and add up the part that falls off with an explicit stack.
  const sumBelow = (start) => {
    let total = 0;
    const todo = [start];
    while (todo.length) {
      const node = todo.pop();
      total += node.val;
      if (node.left) todo.push(node.left);
      if (node.right) todo.push(node.right);
    }
    return total;
  };
  const nodes = [];
  const queue = [root];
  for (let i = 0; i < queue.length; i++) {
    nodes.push(queue[i]);
    if (queue[i].left) queue.push(queue[i].left);
    if (queue[i].right) queue.push(queue[i].right);
  }
  const whole = sumBelow(root);
  let best = -1;
  for (const node of nodes) {
    if (node === root) continue;
    const part = sumBelow(node);
    if (part * (whole - part) > best) best = part * (whole - part);
  }
  return best % 1000000007;
}

