function generate(rand, size) {
  const pick = (k) => Math.floor(rand() * k);
  const n = size === 'large' ? 900 + pick(100) : 2 + pick(11);
  const maxVal = rand() < 0.3 ? 10 : 10000;
  // 0: random shape, 1: a chain (deep), 2: a complete tree.
  const shape = pick(3);
  const nodes = [{ val: 1 + pick(maxVal), left: null, right: null }];
  const slots = [[0, 'left'], [0, 'right']];
  for (let i = 1; i < n; i++) {
    let parent, side;
    if (shape === 1) {
      parent = i - 1;
      side = rand() < 0.5 ? 'left' : 'right';
    } else if (shape === 2) {
      parent = (i - 1) >> 1;
      side = i % 2 === 1 ? 'left' : 'right';
    } else {
      const k = pick(slots.length);
      [parent, side] = slots[k];
      slots[k] = slots[slots.length - 1];
      slots.pop();
      slots.push([i, 'left'], [i, 'right']);
    }
    nodes[parent][side] = i;
    nodes.push({ val: 1 + pick(maxVal), left: null, right: null });
  }
  // Level-order serialisation with null for missing children, trailing nulls removed.
  const out = [nodes[0].val];
  const queue = [0];
  for (let q = 0; q < queue.length; q++) {
    for (const side of ['left', 'right']) {
      const child = nodes[queue[q]][side];
      if (child === null) {
        out.push(null);
      } else {
        out.push(nodes[child].val);
        queue.push(child);
      }
    }
  }
  while (out[out.length - 1] === null) out.pop();
  return [out];
}
